def find_nearest_woman(image):
    image_patch = ImagePatch(image)
    women_patches = image_patch.find("woman")
    if not women_patches:
        return "No women found in the image."

    min_distance = float('inf')
    nearest_woman = None

    for woman_patch in women_patches:
        camera_position = image_patch.crop(0, 0, image.width, image.height).center
        woman_position = woman_patch.center
        distance_to_camera = math.sqrt((camera_position[0] - woman_position[0]) ** 2 + (camera_position[1] - woman_position[1]) ** 2)

        if distance_to_camera < min_distance:
            min_distance = distance_to_camera
            nearest_woman = woman_patch

    return nearest_woman.llm_query("Who is the nearest woman to the camera?", long_answer=False)

